  if($a==='delete'){DB::q("UPDATE jobs SET status='cancelled' WHERE type='auto' AND status='pending' AND ref_id IN (SELECT id FROM automation_runs WHERE automation_id=?)",[$id]);DB::q('DELETE FROM automation_runs WHERE automation_id=?',[$id]);DB::q('DELETE FROM automations WHERE id=?',[$id]);flash('Automation deleted.');}
  if($a==='template'){$t=Automation::templates()[$_POST['t']]??null;if($t){$nid=DB::insert('automations',['name'=>$t['name'],'trig'=>$t['trig'],'trig_value'=>$t['tv']??'','conditions'=>je($t['cond']??[]),'steps'=>je($t['steps']),'stop_on_reply'=>1,'active'=>0]);flash('Template added – review it and switch it on.');redirect(url('automation',['id'=>$nid]));}}
  redirect(url('automations'));}
$rows=DB::all("SELECT a.*,(SELECT COUNT(*) FROM automation_runs r WHERE r.automation_id=a.id AND r.status IN ('running','waiting')) act,(SELECT COUNT(*) FROM automation_runs r WHERE r.automation_id=a.id AND r.status='done') dn FROM automations a ORDER BY a.active DESC,a.id DESC");
