<div class="card p0"><div class="tw"><table class="tbl"><thead><tr><th>On</th><th>Automation</th><th>When</th><th>Steps</th><th>Running</th><th>Completed</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$st=jd($r['steps']);?><tr><td><label class="sw"><input type="checkbox" <?=$r['active']?'checked':''?> onchange="A.post('index.php?r=api&do=toggle_auto',{id:<?=$r['id']?>,on:this.checked?1:''}).then(function(){A.toast('Saved')})"><i></i></label></td><td><a href="<?=url('automation',['id'=>$r['id']])?>"><b><?=e($r['name'])?></b></a></td><td class="sm"><?=e($T[$r['trig']][0]??$r['trig'])?><?=$r['trig_value']!==''?' <b>'.e($r['trig_value']).'</b>':''?></td><td><div class="au-flow"><?php foreach(array_slice($st,0,6) as $s):$x=$AC[$s['t']]??['?','zap','gray'];?><span><?=icon($x[1])?><?=e($s['t']==='wait'?(int)($s['n']??1).' '.($s['u']??'h'):$x[0])?></span><?php endforeach?><?=count($st)>6?'<span>+'.(count($st)-6).'</span>':''?></div></td><td><?=(int)$r['act']?></td><td><?=(int)$r['dn']?></td><td class="act"><a class="ib" href="<?=url('automation',['id'=>$r['id']])?>"><?=icon('edit')?></a><form method="post" onsubmit="return confirm('Delete this automation?')"><?=csrf_field()?><input type="hidden" name="a" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="ib red"><?=icon('trash')?></button></form></td></tr><?php endforeach?></tbody></table></div></div><?php endif?>
<h3 style="margin:8px 0 14px">Ready-made recipes</h3><div class="g31"><?php foreach(Automation::templates() as $k=>$t):?><form method="post" class="card"><?=csrf_field()?><input type="hidden" name="a" value="template"><input type="hidden" name="t" value="<?=$k?>"><div class="au-card"><span class="hi hi-<?=$t['c']?>"><?=icon($t['i'])?></span><div><b><?=e($t['name'])?></b><p class="hint mt0"><?=e($t['desc'])?></p></div></div><div class="au-flow mt"><?php foreach($t['steps'] as $s):$x=$AC[$s['t']];?><span><?=icon($x[1])?><?=e($s['t']==='wait'?$s['n'].' '.$s['u']:$x[0])?></span><?php endforeach?></div><button class="btn btn-sm mt"><?=icon('plus')?>Use recipe</button></form><?php endforeach?></div>
